function blankComp(){return{id:uid(),name:'',amount:'',unit:'g',dbMatchId:'',source:'Custom',kcalOverride:'',proteinOverride:'',fatOverride:'',mctOverride:'',choOverride:'',calciumOverride:'',sodiumOverride:'',potassiumOverride:'',note:''}}function blankFeed(){return{id:uid(),time:'',prescribed:'',actual:'',note:''}}
function componentCalc(c){const f=c.dbMatchId?state.foodDB.find(x=>x.id===c.dbMatchId):exactCustom(c.name);if(!f)return emptyNut();const fac=factorFor({amount:c.amount,unit:c.unit,convertUnit:c.unit,dbMatchId:f.id,convertFood:f.name,weight_g:'',volume_ml:String(c.unit).toLowerCase()==='ml'?c.amount:''},f);if(fac===null)return emptyNut();const t=emptyNut();addNut(t,f,fac);return t}
function modularTotals(mod=state.modular){const t=emptyNut();(mod.components||[]).forEach(c=>{const x=componentCalc(c);TOTAL_KEYS.forEach(k=>t[k]+=x[k])});return t}
function renderModular(){if($('modularSaveStatus'))$('modularSaveStatus').innerHTML=modularDirty?'<span class="dirty-pill">Unsaved changes</span>':'<span class="saved-pill">Saved</span>';const md=ensureModularDraft();$('modName').value=md.name||'';$('modFinalVolume').value=md.finalVolume||'';$('modNotes').value=md.notes||'';const c=$('modComponents');c.innerHTML='';md.components.forEach(comp=>{const selected=comp.dbMatchId?state.foodDB.find(x=>x.id===comp.dbMatchId):exactCustom(comp.name),cands=customDbCandidates(comp.name),units=unitsForIngredient({dbMatchId:selected?.id||'',food:comp.name,unit:comp.unit,convertUnit:comp.unit,convertFood:selected?.name||''});const r=document.createElement('div');r.className='mod-row';r.innerHTML=`<label>Reported component<input data-k="name" value="${esc(comp.name)}"></label><label>Custom DB match<select data-k="dbMatchId"><option value="">— choose —</option>${cands.map(x=>`<option value="${x.id}" ${selected?.id===x.id?'selected':''}>[${esc(x.type)}] ${esc(x.name)}</option>`).join('')}</select></label><label>Amount<input data-k="amount" type="number" step="0.1" value="${esc(comp.amount)}"></label><label>Unit<select data-k="unit"><option value="">— unit —</option>${units.map(u=>`<option value="${esc(u)}" ${comp.unit===u?'selected':''}>${esc(u)}</option>`).join('')}</select></label><button class="small-btn danger">Delete</button>`;r.querySelectorAll('[data-k]').forEach(el=>el.addEventListener('change',()=>{const k=el.dataset.k;comp[k]=el.value;comp.source='Custom';if(k==='dbMatchId'){const f=state.foodDB.find(x=>x.id===el.value);if(f)comp.name=comp.name||f.name;}markModularDirty();renderModular()}));r.querySelector('button').onclick=()=>{md.components=md.components.filter(x=>x.id!==comp.id);markModularDirty();renderModular()};c.appendChild(r)});const f=$('feedSchedule');f.innerHTML='';md.feeds.forEach(feed=>{const r=document.createElement('div');r.className='feed-row';r.innerHTML=`<label>Time<input data-k="time" value="${esc(feed.time)}"></label><label>Prescribed mL<input data-k="prescribed" type="number" value="${esc(feed.prescribed)}"></label><label>Actual mL<input data-k="actual" type="number" value="${esc(feed.actual)}"></label><label>% consumed<input disabled value="${feed.prescribed?round(num(feed.actual)/num(feed.prescribed)*100,1):0}%"></label><label>Note<input data-k="note" value="${esc(feed.note)}"></label><button class="small-btn danger">Delete</button>`;r.querySelectorAll('[data-k]').forEach(el=>el.addEventListener('change',()=>{feed[el.dataset.k]=el.value;markModularDirty();renderModular()}));r.querySelector('button').onclick=()=>{md.feeds=md.feeds.filter(x=>x.id!==feed.id);markModularDirty();renderModular()};f.appendChild(r)});renderModularSummary()}
function renderModularSummary(){const md=ensureModularDraft(),t=modularTotals(md),vol=num(md.finalVolume),pres=(md.feeds||[]).reduce((s,x)=>s+num(x.prescribed),0),act=(md.feeds||[]).reduce((s,x)=>s+num(x.actual),0),ratio=vol?act/vol:0;$('modRecipeSummary').innerHTML=`<div class="summary-grid"><div class="metric">Recipe energy<b>${round(t.kcal)} kcal</b></div><div class="metric">Protein<b>${round(t.protein)} g</b></div><div class="metric">Fat<b>${round(t.fat)} g</b></div><div class="metric">MCT<b>${round(t.mct)} g</b></div><div class="metric">CHO<b>${round(t.cho)} g</b></div><div class="metric">Concentration<b>${vol?round(t.kcal/vol,3)+' kcal/mL':'—'}</b></div></div>`;$('feedSummary').innerHTML=`<div class="summary-grid"><div class="metric">Prescribed<b>${round(pres)} mL/day</b></div><div class="metric">Actual<b>${round(act)} mL/day</b></div><div class="metric">Consumed<b>${pres?round(act/pres*100,1):0}%</b></div><div class="metric">Actual energy<b>${round(t.kcal*ratio)} kcal</b></div><div class="metric">Actual protein<b>${round(t.protein*ratio)} g</b></div><div class="metric">Actual fat<b>${round(t.fat*ratio)} g</b></div></div>`}
['modName','modFinalVolume','modNotes'].forEach(id=>$(id).addEventListener('change',()=>{const md=ensureModularDraft(),k=id==='modName'?'name':id==='modFinalVolume'?'finalVolume':'notes';md[k]=$(id).value;markModularDirty();renderModularSummary()}));$('addModComponentBtn').onclick=()=>{const md=ensureModularDraft();md.components.push(blankComp());markModularDirty();renderModular()};$('addFeedBtn').onclick=()=>{const md=ensureModularDraft();md.feeds.push(blankFeed());markModularDirty();renderModular()};$('saveModularBtn').onclick=()=>{state.modular=clone(ensureModularDraft());saveState();resetModularDraft();renderModular();renderModularSummary()};$('cancelModularBtn').onclick=()=>{resetModularDraft();renderModular()};



// 0.4.19 Diet Design / Nutrition Prescription
let designDraft=null,designDirty=false;
function ensureDesignDraft(){if(!designDraft)designDraft=clone(state.dietDesign||blankDietDesign());return designDraft}
function resetDesignDraft(){designDraft=clone(state.dietDesign||blankDietDesign());designDirty=false}
function markDesignDirty(){designDirty=true;if($('designSaveStatus'))$('designSaveStatus').innerHTML='<span class="dirty-pill">Unsaved changes</span>'}
function sumNut(parts){const t=emptyNut();(parts||[]).forEach(x=>TOTAL_KEYS.forEach(k=>t[k]+=num(x?.[k])));return t}
function sourceRowCalc(row, opts={}){
  const f=row.dbMatchId?state.foodDB.find(x=>x.id===row.dbMatchId):exactCustom(row.name);
  if(!f)return {nut:emptyNut(),ok:false,reason:'ยังไม่ได้เลือก Custom DB item',food:null,factor:null};
  let amount=num(row.amount),unit=row.unit||f.basis_unit,volume='';
  const box=String(unit).match(/^กล่อง\s*(180|200|225)\s*mL$/i);
  if(box){volume=amount*num(box[1]);amount=volume;unit='mL'}
  let mult=1;
  if(opts.mode==='per_feed')mult=Math.max(0,num(opts.feeds));
  const x={amount:amount*mult,unit,convertUnit:unit,dbMatchId:f.id,convertFood:f.name,weight_g:'',volume_ml:volume!==''?volume*mult:(String(unit).toLowerCase()==='ml'?amount*mult:''),formulaKcalOz:opts.kcalPerOz||''};
  const fac=factorFor(x,f);
  if(fac===null||!Number.isFinite(fac))return {nut:emptyNut(),ok:false,reason:'หน่วย/ปริมาณยังคำนวณกับ DB item นี้ไม่ได้',food:f,factor:null};
  const t=emptyNut();addNut(t,f,fac);return {nut:t,ok:true,reason:'',food:f,factor:fac,used:x};
}
function dietDesignCalc(d=ensureDesignDraft()){
  const rows=[],parts=[];
  if(d.dietEnabled)(d.dietItems||[]).forEach(r=>{const c=sourceRowCalc(r);rows.push({...c,row:r,section:'Diet'});if(c.ok)parts.push(c.nut)});
  return {total:sumNut(parts),rows};
}
function formulaDesignCalc(d=ensureDesignDraft()){
  const rows=[],parts=[];let fluid=0;
  if(d.formulaEnabled)(d.formulaPlans||[]).forEach(p=>{
    const mode=p.mode||'per_day',feeds=mode==='per_feed'?Math.max(0,num(p.feeds)):1;
    const c=sourceRowCalc(p,{mode,feeds,kcalPerOz:p.kcalPerOz});rows.push({...c,row:p,section:'Formula base'});if(c.ok)parts.push(c.nut);
    let per=num(p.amount),u=p.unit||'mL';const bx=String(u).match(/^กล่อง\s*(180|200|225)\s*mL$/i);if(bx)per*=num(bx[1]);if(String(u).toLowerCase()==='ml'||bx)fluid+=per*feeds;
    (p.fortifiers||[]).forEach(ft=>{const fc=sourceRowCalc(ft,{mode:ft.mode||'per_day',feeds});rows.push({...fc,row:ft,section:'Fortifier'});if(fc.ok)parts.push(fc.nut)});
  });
  return {total:sumNut(parts),rows,fluid};
}
function designModularCalc(d=ensureDesignDraft()){
  const m=d.modular||blankDietDesign().modular,rows=[],recipeParts=[];
  if(d.modularEnabled)(m.components||[]).forEach(r=>{const c=sourceRowCalc(r);rows.push({...c,row:r,section:'Modular component'});if(c.ok)recipeParts.push(c.nut)});
  const recipe=sumNut(recipeParts),finalVol=num(m.finalVolume),dailyVol=num(m.feedVolume)*num(m.feeds),ratio=finalVol>0?dailyVol/finalVol:0,daily=emptyNut();TOTAL_KEYS.forEach(k=>daily[k]=recipe[k]*ratio);
  return {recipe,daily,rows,finalVol,dailyVol,ratio};
}
function designCombined(d=ensureDesignDraft()){
  const di=dietDesignCalc(d),fo=formulaDesignCalc(d),mo=designModularCalc(d),total=sumNut([di.total,fo.total,mo.daily]);
  const fluid=fo.fluid+(d.modularEnabled?mo.dailyVol:0)+num(d.fluid?.freeWater)+num(d.fluid?.otherFluid);
  const problems=[...di.rows,...fo.rows,...mo.rows].filter(x=>!x.ok);
  return {diet:di,formula:fo,modular:mo,total,fluid,problems};
}
function nutrientMetricGrid(t){return `<div class="summary-grid"><div class="metric">Energy<b>${round(t.kcal,1)} kcal</b></div><div class="metric">Protein<b>${round(t.protein,2)} g</b></div><div class="metric">CHO<b>${round(t.cho,1)} g</b></div><div class="metric">Fat<b>${round(t.fat,1)} g</b></div><div class="metric">MCT<b>${round(t.mct,1)} g</b></div><div class="metric">Calcium<b>${round(t.calcium,1)} mg</b></div><div class="metric">Na<b>${round(t.sodium,1)} mg</b><span>${round(t.sodium/23,2)} mEq</span></div><div class="metric">K<b>${round(t.potassium,1)} mg</b><span>${round(t.potassium/39,2)} mEq</span></div></div>`}
function requirementCell(value,target,unit){if(!target)return `${round(value,1)} ${unit}`;return `${round(value,1)} / ${round(target,1)} ${unit}<br><span class="muted">${round(value/target*100,1)}%</span>`}
function renderDesignTargets(){const r=state.requirements,w=num(state.patient.weight);$('designTargetSummary').innerHTML=`<strong>Targets from Patient Profile</strong><div class="summary-grid top-gap"><div class="metric">Energy<b>${r.energy?esc(r.energy)+' kcal/day':'—'}</b></div><div class="metric">Protein<b>${r.protein?esc(r.protein)+' g/day':'—'}</b>${w&&r.protein?`<span>${round(num(r.protein)/w,2)} g/kg/day</span>`:''}</div><div class="metric">Fat<b>${r.fatPct?esc(r.fatPct)+'% energy':'—'}</b></div><div class="metric">MCT<b>${r.mctPct?esc(r.mctPct)+'% energy':'—'}</b></div><div class="metric">Calcium<b>${r.calcium?esc(r.calcium)+' mg/day':'—'}</b></div><div class="metric">Na<b>${r.sodium?esc(r.sodium)+' mg/day':'—'}</b>${r.sodium?`<span>${round(num(r.sodium)/23,2)} mEq</span>`:''}</div><div class="metric">K<b>${r.potassium?esc(r.potassium)+' mg/day':'—'}</b>${r.potassium?`<span>${round(num(r.potassium)/39,2)} mEq</span>`:''}</div><div class="metric">Fluid<b>${r.trackFluid&&r.fluid?esc(r.fluid)+' mL/day':'Not tracked'}</b></div></div>`}
function renderDesignRemaining(){const c=designCombined(),r=state.requirements;const rem=(v,t)=>t?round(num(t)-num(v),1):'—';$('designRemaining').innerHTML=`<strong>Remaining after current prescription</strong><div class="summary-grid top-gap"><div class="metric">Energy remaining<b>${rem(c.total.kcal,r.energy)} ${r.energy?'kcal':'—'}</b></div><div class="metric">Protein remaining<b>${rem(c.total.protein,r.protein)} ${r.protein?'g':'—'}</b></div><div class="metric">Calcium remaining<b>${rem(c.total.calcium,r.calcium)} ${r.calcium?'mg':'—'}</b></div><div class="metric">Na remaining<b>${rem(c.total.sodium,r.sodium)} ${r.sodium?'mg':'—'}</b></div><div class="metric">K remaining<b>${rem(c.total.potassium,r.potassium)} ${r.potassium?'mg':'—'}</b></div><div class="metric">Tracked fluid<b>${r.trackFluid?round(c.fluid,0)+' mL/day':'Not tracked'}</b></div></div><p class="muted top-gap">ระบบไม่เลือก Diet : Formula : Modular ให้เองโดยอัตโนมัติ; ผู้ใช้กำหนด source และปริมาณ แล้ว Remaining จะคำนวณทันทีเพื่อช่วยปรับ prescription โดยไม่ใช้ black-box allocation.</p>`}
function candidateOptions(selectedId='',filterFn=null){const arr=(state.foodDB||[]).filter(f=>!filterFn||filterFn(f));return `<option value="">— choose from Custom DB —</option>${arr.map(f=>`<option value="${f.id}" ${selectedId===f.id?'selected':''}>[${esc(f.type)}] ${esc(f.name)}</option>`).join('')}`}
function unitsForDesignRow(r){const f=r.dbMatchId?state.foodDB.find(x=>x.id===r.dbMatchId):null;const set=new Set(['g','mL']);if(f){if(f.basis_unit)set.add(f.basis_unit);savedConversions(f).forEach(c=>set.add(c.unit));(f.portions||[]).forEach(c=>set.add(c.unit));state.portionDB.filter(x=>x.food===f.name||(x.aliases||[]).includes(f.name)).forEach(x=>set.add(x.unit));if(num(f.grams_per_scoop)>0)set.add('scoop')}if(r.unit)set.add(r.unit);return [...set].filter(Boolean)}
function renderDietRows(d){const box=$('designDietRows');box.innerHTML='';(d.dietItems||[]).forEach(r=>{const el=document.createElement('div');el.className='design-row';const units=unitsForDesignRow(r);el.innerHTML=`<label>Group<select data-k="group"><option value="starch" ${r.group==='starch'?'selected':''}>Rice / starch</option><option value="meat" ${r.group==='meat'?'selected':''}>Meat</option><option value="egg" ${r.group==='egg'?'selected':''}>Egg</option><option value="vegetable" ${r.group==='vegetable'?'selected':''}>Vegetable</option><option value="fruit" ${r.group==='fruit'?'selected':''}>Fruit</option><option value="other" ${r.group==='other'?'selected':''}>Other</option></select></label><label>Custom DB item<select data-k="dbMatchId">${candidateOptions(r.dbMatchId)}</select></label><label>Amount<input data-k="amount" type="number" step="0.1" value="${esc(r.amount)}"></label><label>Unit<select data-k="unit">${units.map(u=>`<option value="${esc(u)}" ${r.unit===u?'selected':''}>${esc(u)}</option>`).join('')}</select></label><button class="small-btn danger">Delete</button>`;el.querySelectorAll('[data-k]').forEach(i=>i.addEventListener('change',()=>{r[i.dataset.k]=i.value;if(i.dataset.k==='dbMatchId'){const f=state.foodDB.find(x=>x.id===i.value);r.name=f?.name||'';if(f&&!r.unit)r.unit=f.basis_unit}markDesignDirty();renderDietDesign()}));el.querySelector('button').onclick=()=>{d.dietItems=d.dietItems.filter(x=>x.id!==r.id);markDesignDirty();renderDietDesign()};box.appendChild(el)});if(!d.dietItems.length)box.innerHTML='<p class="muted">ยังไม่มีรายการอาหาร</p>'}
function renderFormulaPlans(d){const box=$('formulaPlanRows');box.innerHTML='';(d.formulaPlans||[]).forEach(p=>{const card=document.createElement('div');card.className='formula-plan-card';const units=['mL','กล่อง 180 mL','กล่อง 200 mL','กล่อง 225 mL',...unitsForDesignRow(p).filter(x=>x!=='mL')];card.innerHTML=`<div class="formula-plan-grid"><label>Milk / Formula<select data-k="dbMatchId">${candidateOptions(p.dbMatchId,f=>f.type==='formula'||f.protein_source==='milk')}</select></label><label>Amount<input data-k="amount" type="number" step="0.1" value="${esc(p.amount)}"></label><label>Unit<select data-k="unit">${[...new Set(units)].map(u=>`<option value="${esc(u)}" ${p.unit===u?'selected':''}>${esc(u)}</option>`).join('')}</select></label><label>Given<select data-k="mode"><option value="per_day" ${p.mode==='per_day'?'selected':''}>per day</option><option value="per_feed" ${p.mode==='per_feed'?'selected':''}>per feed</option></select></label><label>Feeds/day<input data-k="feeds" type="number" step="1" value="${esc(p.feeds)}"></label><label>kcal/oz <span class="muted">powder formula</span><input data-k="kcalPerOz" type="number" step="0.1" value="${esc(p.kcalPerOz)}"></label><button class="small-btn danger remove-plan">Delete milk/formula</button></div><div class="section-title-row top-gap"><strong>Fortification</strong><button class="small-btn secondary add-fort">+ Add fortifier</button></div><div class="fortifier-box"></div>`;
    card.querySelectorAll('.formula-plan-grid [data-k]').forEach(i=>i.addEventListener('change',()=>{p[i.dataset.k]=i.value;if(i.dataset.k==='dbMatchId'){const f=state.foodDB.find(x=>x.id===i.value);p.name=f?.name||''}markDesignDirty();renderDietDesign()}));card.querySelector('.remove-plan').onclick=()=>{d.formulaPlans=d.formulaPlans.filter(x=>x.id!==p.id);markDesignDirty();renderDietDesign()};card.querySelector('.add-fort').onclick=()=>{p.fortifiers.push(blankFortifier());markDesignDirty();renderDietDesign()};const fb=card.querySelector('.fortifier-box');(p.fortifiers||[]).forEach(ft=>{const row=document.createElement('div');row.className='fortifier-row';const units2=unitsForDesignRow(ft);row.innerHTML=`<label>Fortifier<select data-k="dbMatchId">${candidateOptions(ft.dbMatchId)}</select></label><label>Amount<input data-k="amount" type="number" step="0.1" value="${esc(ft.amount)}"></label><label>Unit<select data-k="unit">${units2.map(u=>`<option value="${esc(u)}" ${ft.unit===u?'selected':''}>${esc(u)}</option>`).join('')}</select></label><label>Given<select data-k="mode"><option value="per_day" ${ft.mode==='per_day'?'selected':''}>per day</option><option value="per_feed" ${ft.mode==='per_feed'?'selected':''}>per feed</option></select></label><button class="small-btn danger">Delete</button>`;row.querySelectorAll('[data-k]').forEach(i=>i.addEventListener('change',()=>{ft[i.dataset.k]=i.value;if(i.dataset.k==='dbMatchId'){const f=state.foodDB.find(x=>x.id===i.value);ft.name=f?.name||''}markDesignDirty();renderDietDesign()}));row.querySelector('button').onclick=()=>{p.fortifiers=p.fortifiers.filter(x=>x.id!==ft.id);markDesignDirty();renderDietDesign()};fb.appendChild(row)});box.appendChild(card)});if(!d.formulaPlans.length)box.innerHTML='<p class="muted">ยังไม่มี milk/formula prescription</p>'}
function renderDesignModComponents(d){const box=$('designModComponents'),m=d.modular;box.innerHTML='';(m.components||[]).forEach(r=>{const el=document.createElement('div');el.className='design-row';const units=unitsForDesignRow(r);el.innerHTML=`<label>Component<select data-k="dbMatchId">${candidateOptions(r.dbMatchId)}</select></label><label>Amount<input data-k="amount" type="number" step="0.1" value="${esc(r.amount)}"></label><label>Unit<select data-k="unit">${units.map(u=>`<option value="${esc(u)}" ${r.unit===u?'selected':''}>${esc(u)}</option>`).join('')}</select></label><div class="muted component-kind">${esc((state.foodDB.find(x=>x.id===r.dbMatchId)?.type)||'')}</div><button class="small-btn danger">Delete</button>`;el.querySelectorAll('[data-k]').forEach(i=>i.addEventListener('change',()=>{r[i.dataset.k]=i.value;if(i.dataset.k==='dbMatchId'){const f=state.foodDB.find(x=>x.id===i.value);r.name=f?.name||'';if(f&&!r.unit)r.unit=f.basis_unit}markDesignDirty();renderDietDesign()}));el.querySelector('button').onclick=()=>{m.components=m.components.filter(x=>x.id!==r.id);markDesignDirty();renderDietDesign()};box.appendChild(el)});if(!m.components.length)box.innerHTML='<p class="muted">ยังไม่มี component</p>'}
function recheckTable(title,calcRows,total,extra=''){const rows=calcRows.map(x=>`<tr><td>${esc(x.section)}</td><td>${esc(x.food?.name||x.row?.name||'—')}</td><td>${esc(x.row?.amount||'—')} ${esc(x.row?.unit||'')}</td><td>${x.ok?round(x.nut.kcal,1):'—'}</td><td>${x.ok?round(x.nut.protein,2):'—'}</td><td>${x.ok?round(x.nut.cho,1):'—'}</td><td>${x.ok?round(x.nut.fat,1):'—'}</td><td>${x.ok?round(x.nut.calcium,1):'—'}</td><td>${x.ok?`${round(x.nut.sodium,1)} mg / ${round(x.nut.sodium/23,2)} mEq`:'—'}</td><td>${x.ok?`${round(x.nut.potassium,1)} mg / ${round(x.nut.potassium/39,2)} mEq`:'—'}</td><td>${x.ok?'✓':`⚠ ${esc(x.reason)}`}</td></tr>`).join('');return `<h3 class="top-gap">${title}</h3>${extra}<div class="table-wrap"><table class="design-recheck-table"><thead><tr><th>Source</th><th>DB item</th><th>Amount</th><th>kcal</th><th>Protein</th><th>CHO</th><th>Fat</th><th>Ca</th><th>Na</th><th>K</th><th>Status</th></tr></thead><tbody>${rows||'<tr><td colspan="11">No items</td></tr>'}</tbody><tfoot><tr class="calc-total-row"><th colspan="3">Total</th><th>${round(total.kcal,1)}</th><th>${round(total.protein,2)}</th><th>${round(total.cho,1)}</th><th>${round(total.fat,1)}</th><th>${round(total.calcium,1)}</th><th>${round(total.sodium,1)} mg</th><th>${round(total.potassium,1)} mg</th><th></th></tr></tfoot></table></div>`}
function renderDesignRecheck(){const c=designCombined(),r=state.requirements,m=c.modular;let html=recheckTable('A. Diet',c.diet.rows,c.diet.total)+recheckTable('B. Milk / Formula + Fortifiers',c.formula.rows,c.formula.total,`<p class="muted">Recorded formula/milk fluid: ${round(c.formula.fluid,0)} mL/day</p>`)+recheckTable('C. Modular Diet',m.rows,m.daily,`<p class="muted">Whole recipe: ${round(m.recipe.kcal,1)} kcal • Final volume ${round(m.finalVol,0)} mL • Daily prescribed ${round(m.dailyVol,0)} mL (${round(m.ratio*100,1)}% of recipe)</p>${m.finalVol?`<p class="muted">Per 100 mL: ${round(m.recipe.kcal/m.finalVol*100,1)} kcal • Protein ${round(m.recipe.protein/m.finalVol*100,2)} g • Per feed (${round(num(ensureDesignDraft().modular.feedVolume),0)} mL): ${round(m.recipe.kcal/m.finalVol*num(ensureDesignDraft().modular.feedVolume),1)} kcal</p>`:''}`);
  html+=`<h3 class="top-gap">D. Total Daily Prescription</h3><div class="table-wrap"><table class="design-total-table"><thead><tr><th>Nutrient</th><th>Diet</th><th>Milk/Formula</th><th>Modular</th><th>Total</th><th>Requirement</th><th>% target</th></tr></thead><tbody>${[
    ['Energy','kcal','kcal',r.energy],['Protein','protein','g',r.protein],['CHO','cho','g',''],['Fat','fat','g',''],['MCT','mct','g',''],['Calcium','calcium','mg',r.calcium],['Sodium','sodium','mg',r.sodium],['Potassium','potassium','mg',r.potassium]
  ].map(([label,k,u,target])=>`<tr><td>${label}</td><td>${round(c.diet.total[k],2)}</td><td>${round(c.formula.total[k],2)}</td><td>${round(c.modular.daily[k],2)}</td><td><strong>${round(c.total[k],2)} ${u}</strong>${k==='sodium'?`<br><span class="muted">${round(c.total[k]/23,2)} mEq</span>`:''}${k==='potassium'?`<br><span class="muted">${round(c.total[k]/39,2)} mEq</span>`:''}</td><td>${target?esc(target)+' '+u:'—'}</td><td>${target?round(c.total[k]/num(target)*100,1)+'%':'—'}</td></tr>`).join('')}</tbody></table></div>`;
  const totalProtein=c.total.protein||0;html+=`<div class="summary-box top-gap"><strong>Actual source contribution</strong><p>Protein: Diet ${totalProtein?round(c.diet.total.protein/totalProtein*100,1):0}% • Milk/Formula ${totalProtein?round(c.formula.total.protein/totalProtein*100,1):0}% • Modular ${totalProtein?round(c.modular.daily.protein/totalProtein*100,1):0}%</p><p>Energy: Diet ${c.total.kcal?round(c.diet.total.kcal/c.total.kcal*100,1):0}% • Milk/Formula ${c.total.kcal?round(c.formula.total.kcal/c.total.kcal*100,1):0}% • Modular ${c.total.kcal?round(c.modular.daily.kcal/c.total.kcal*100,1):0}%</p></div>`;
  if(r.trackFluid)html+=`<div class="summary-box top-gap"><strong>Fluid Recheck</strong><p>Milk/Formula ${round(c.formula.fluid,0)} mL/day • Modular delivered ${round(c.modular.dailyVol,0)} mL/day • Free water/flush ${round(num(ensureDesignDraft().fluid.freeWater),0)} mL/day • Other recorded ${round(num(ensureDesignDraft().fluid.otherFluid),0)} mL/day</p><p><strong>Recorded fluid ${round(c.fluid,0)} mL/day</strong>${r.fluid?` • Target ${round(num(r.fluid),0)} mL/day • ${round(c.fluid/num(r.fluid)*100,1)}%`:''}</p></div>`;else html+=`<div class="summary-box top-gap"><strong>Fluid</strong><p class="muted">Not tracked for this case. Enable Track total fluid in Patient Profile when clinically useful.</p></div>`;
  if(c.problems.length)html+=`<div class="warning-box"><strong>Recheck incomplete</strong>${c.problems.map(x=>`<div>${esc(x.food?.name||x.row?.name||'Item')}: ${esc(x.reason)}</div>`).join('')}<div class="muted top-gap">ค่าที่ไม่มีใน Custom Database ไม่ถูกสมมติขึ้นเอง.</div></div>`;
  $('designRecheck').innerHTML=html
}
function renderDietDesign(){const d=ensureDesignDraft();$('designSaveStatus').innerHTML=designDirty?'<span class="dirty-pill">Unsaved changes</span>':'<span class="saved-pill">Saved</span>';$('designDietEnabled').checked=!!d.dietEnabled;$('designFormulaEnabled').checked=!!d.formulaEnabled;$('designModularEnabled').checked=!!d.modularEnabled;renderDesignTargets();renderDietRows(d);renderFormulaPlans(d);const m=d.modular;$('designModName').value=m.name||'';$('designModFinalVolume').value=m.finalVolume||'';$('designModNote').value=m.note||'';$('designModFeedVolume').value=m.feedVolume||'';$('designModFeeds').value=m.feeds||'';$('designModDailyVolume').value=num(m.feedVolume)*num(m.feeds)||'';renderDesignModComponents(d);$('designFreeWater').value=d.fluid?.freeWater||'';$('designOtherFluid').value=d.fluid?.otherFluid||'';$('designFluidNote').value=d.fluid?.note||'';const c=designCombined(d);$('dietDesignSummary').innerHTML=nutrientMetricGrid(c.diet.total);$('formulaDesignSummary').innerHTML=nutrientMetricGrid(c.formula.total);$('modularDesignSummary').innerHTML=`<strong>Daily delivered modular diet</strong>${nutrientMetricGrid(c.modular.daily)}<p class="muted top-gap">Whole recipe ${round(c.modular.recipe.kcal,1)} kcal • final volume ${round(c.modular.finalVol,0)} mL • prescribed ${round(c.modular.dailyVol,0)} mL/day</p>`;renderDesignRemaining();renderDesignRecheck()}
['designDietEnabled','designFormulaEnabled','designModularEnabled'].forEach(id=>$(id).addEventListener('change',()=>{const d=ensureDesignDraft();d[id==='designDietEnabled'?'dietEnabled':id==='designFormulaEnabled'?'formulaEnabled':'modularEnabled']=$(id).checked;markDesignDirty();renderDietDesign()}));
$('addDesignDietBtn').onclick=()=>{ensureDesignDraft().dietItems.push(blankDesignDietItem());markDesignDirty();renderDietDesign()};$('addFormulaPlanBtn').onclick=()=>{ensureDesignDraft().formulaPlans.push(blankFormulaPlan());markDesignDirty();renderDietDesign()};$('addDesignModCompBtn').onclick=()=>{ensureDesignDraft().modular.components.push(blankDesignModComp());markDesignDirty();renderDietDesign()};
[['designModName','name'],['designModFinalVolume','finalVolume'],['designModNote','note'],['designModFeedVolume','feedVolume'],['designModFeeds','feeds']].forEach(([id,k])=>$(id).addEventListener('change',()=>{ensureDesignDraft().modular[k]=$(id).value;markDesignDirty();renderDietDesign()}));[['designFreeWater','freeWater'],['designOtherFluid','otherFluid'],['designFluidNote','note']].forEach(([id,k])=>$(id).addEventListener('change',()=>{ensureDesignDraft().fluid[k]=$(id).value;markDesignDirty();renderDietDesign()}));
$('refreshDesignRecheckBtn').onclick=()=>{renderDesignRemaining();renderDesignRecheck()};$('saveDesignBtn').onclick=()=>{state.dietDesign=clone(ensureDesignDraft());saveState();resetDesignDraft();renderDietDesign()};$('cancelDesignBtn').onclick=()=>{resetDesignDraft();renderDietDesign()};
$('sendDesignToDailyModularBtn').onclick=()=>{const d=ensureDesignDraft(),m=d.modular;if(!d.modularEnabled&&!confirm('Modular Diet is currently disabled in Diet Design. Copy recipe anyway?'))return;const feedVol=num(m.feedVolume),feeds=Math.max(0,Math.floor(num(m.feeds)));state.modular={name:m.name||'Designed modular recipe',finalVolume:m.finalVolume||'',notes:m.note||'',components:(m.components||[]).map(x=>({id:uid(),name:x.name||state.foodDB.find(f=>f.id===x.dbMatchId)?.name||'',amount:x.amount,unit:x.unit,dbMatchId:x.dbMatchId,source:'Custom',note:''})),feeds:Array.from({length:feeds},(_,i)=>({id:uid(),time:'',prescribed:feedVol||'',actual:'',note:`Feed ${i+1}`})),route:'',durationHr:''};saveState();resetModularDraft();renderModular();alert('Copied to Daily Modular Diet. Review and Save/adjust actual intake in the Modular Diet tab.')};

$('defaultSource').addEventListener('change',()=>{state.settings.defaultSource='Custom';$('defaultSource').value='Custom';saveState()});$('exportBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ped-nutrition-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)});$('importBackupInput').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{state=merge(defaultState,JSON.parse(await f.text()));saveState();foodDbDraft=null;foodDbDirty=false;resetReviewDraft();resetModularDraft();resetDesignDraft();renderPatient();renderMeals();renderFoodDB();renderModular();renderDietDesign();alert('Restore สำเร็จ')}catch{alert('Backup ไม่ถูกต้อง')}});$('resetBtn').addEventListener('click',()=>{if(confirm('This will permanently delete local patient/case data and custom data on this device. Export a backup first. Continue?')){localStorage.removeItem('pedNutritionStateV4');localStorage.removeItem('pedNutritionStateV3');location.reload()}});

resetDesignDraft();renderPatient();renderMeals();renderFoodDB();renderModular();renderDietDesign();
